/**
 * FBT pradinis konfiguravimas — sausas maistas → skanestai
 * v2 — pataisyti apostrofai (Code Snippets compatible)
 *
 * Naudojimas:
 *   1. Dry run:     /?fbt_setup=1
 *   2. Pritaikyti:  /?fbt_setup=1&confirm=1
 */

add_action( 'init', function() {
    if ( empty( $_GET['fbt_setup'] ) ) return;
    if ( ! current_user_can( 'manage_options' ) ) wp_die( 'Reikia admin teisiu.' );

    $confirm = ! empty( $_GET['confirm'] );

    // ============ TIKSLAS ============
    $target_pairs = [
        'sausas-maistas-sunims' => [ 'skanestai-sunims' ],
        'sausas-maistas-katems' => [ 'skanestai-katems' ],
    ];
    $target_rules = [
        'skanestai-sunims' => 15,
        'skanestai-katems' => 15,
    ];

    // ============ VALIDACIJA ============
    $report = [];
    $errors = [];

    foreach ( $target_pairs as $main_slug => $companions ) {
        $main_term = get_term_by( 'slug', $main_slug, 'product_cat' );
        if ( ! $main_term ) {
            $errors[] = "Pagrindine kategorija NERASTA: <code>{$main_slug}</code>";
            continue;
        }
        $main_count = (int) $main_term->count;
        $companion_info = [];
        foreach ( $companions as $c_slug ) {
            $c_term = get_term_by( 'slug', $c_slug, 'product_cat' );
            if ( ! $c_term ) {
                $errors[] = "Kompanionas NERASTA: <code>{$c_slug}</code>";
                continue;
            }
            $companion_info[] = "{$c_slug} ({$c_term->count} prekes)";
        }
        $report[] = "OK: <code>{$main_slug}</code> ({$main_count} prekes) -> " . implode( ', ', $companion_info );
    }

    foreach ( $target_rules as $slug => $pct ) {
        $term = get_term_by( 'slug', $slug, 'product_cat' );
        if ( ! $term ) {
            $errors[] = "Nuolaidos kategorija NERASTA: <code>{$slug}</code>";
        } else {
            $report[] = "OK: Nuolaida <code>{$slug}</code> = {$pct}%";
        }
    }

    // ============ ATVAIZDAVIMAS ============
    echo '<div style="font-family:system-ui;max-width:800px;margin:40px auto;padding:20px;">';
    echo '<h1>FBT setup — sausas maistas -> skanestai</h1>';

    if ( $errors ) {
        echo '<h2 style="color:#d63638;">Klaidos:</h2><ul>';
        foreach ( $errors as $e ) echo "<li>{$e}</li>";
        echo '</ul>';
        echo '<p><strong>Setupas nevykdomas, kol neispresta klaidu.</strong> Patikrink slugus: Produktai -> Kategorijos.</p>';
        echo '</div>';
        return;
    }

    echo '<h2>Planas:</h2><ul>';
    foreach ( $report as $r ) echo "<li>{$r}</li>";
    echo '</ul>';

    // ============ DABARTINE BUKLE ============
    $current_pairs = get_option( 'petshop_fbt_pairs', [] );
    $current_rules = get_option( 'petshop_fbt_cat_rules', [] );

    echo '<h2>Dabartine bukle (bus PERRASYTA):</h2>';
    echo '<p><strong>Poros:</strong> ' . ( empty( $current_pairs ) ? '<em>tuscia</em>' : '<pre>' . esc_html( print_r( $current_pairs, true ) ) . '</pre>' ) . '</p>';
    echo '<p><strong>Nuolaidos:</strong> ' . ( empty( $current_rules ) ? '<em>tuscia</em>' : '<pre>' . esc_html( print_r( $current_rules, true ) ) . '</pre>' ) . '</p>';

    if ( ! $confirm ) {
        echo '<hr><p><strong>DRY RUN — niekas neissaugota.</strong></p>';
        echo '<p>Pritaikyti: <a href="?fbt_setup=1&confirm=1" style="background:#2271b1;color:#fff;padding:10px 20px;text-decoration:none;border-radius:4px;">Patvirtinti ir issaugoti</a></p>';
        echo '</div>';
        return;
    }

    // ============ IRASYMAS ============
    update_option( 'petshop_fbt_pairs', $target_pairs );
    update_option( 'petshop_fbt_cat_rules', $target_rules );

    echo '<hr style="margin:30px 0;">';
    echo '<h2 style="color:#00a32a;">Issaugota!</h2>';
    echo '<p>Eik i: <a href="' . admin_url( 'admin.php?page=petshop-fbt' ) . '">WooCommerce -> Daznai perkama kartu</a> patikrinti.</p>';
    echo '<p>Testuok: atidaryk AMBROSIA Junior produkto puslapi (arba bet kuri <code>sausas-maistas-sunims</code> arba <code>sausas-maistas-katems</code> produkta).</p>';
    echo '</div>';

    exit;
} );

