		return;
	}
	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}

	global $wpdb;

	// Markeriai, kuriu ieskom
	$markers = [ 'petshop-crosssell', 'petshop_crosssell', 'crosssell__grid', 'Papildykite krep' ];

	header( 'Content-Type: text/plain; charset=utf-8' );
	echo "=== PETSHOP CROSSSELL — kur gyvena kodas ===\n";
	echo "Markeriai: " . implode( ', ', $markers ) . "\n\n";

	$found_any = false;

	// ---------- 1) Code Snippets plugin (lentele {prefix}snippets) ----------
	$cs_table = $wpdb->prefix . 'snippets';
	if ( $wpdb->get_var( $wpdb->prepare( "SHOW TABLES LIKE %s", $cs_table ) ) === $cs_table ) {
		echo "--- Code Snippets plugin ({$cs_table}) ---\n";
		$rows = $wpdb->get_results( "SELECT id, name, scope, active, code FROM {$cs_table}" );
		$hit = false;
		foreach ( (array) $rows as $r ) {
			foreach ( $markers as $m ) {
				if ( stripos( (string) $r->code, $m ) !== false ) {
					echo "  RASTA: snippet ID {$r->id} | '{$r->name}' | scope={$r->scope} | active={$r->active}\n";
					$hit = true; $found_any = true;
					break;
				}
			}
		}
		if ( ! $hit ) echo "  (nerasta)\n";
		echo "\n";
	} else {
		echo "--- Code Snippets plugin: lentele {$cs_table} neegzistuoja (gal nenaudojamas) ---\n\n";
	}

	// ---------- 2) WPCode plugin (lentele {prefix}wpcode) ----------
	$wc_table = $wpdb->prefix . 'wpcode';
	if ( $wpdb->get_var( $wpdb->prepare( "SHOW TABLES LIKE %s", $wc_table ) ) === $wc_table ) {
		echo "--- WPCode plugin ({$wc_table}) ---\n";
		$rows = $wpdb->get_results( "SELECT id, title, code FROM {$wc_table}" );
		$hit = false;
		foreach ( (array) $rows as $r ) {
			foreach ( $markers as $m ) {
				if ( stripos( (string) $r->code, $m ) !== false ) {
					echo "  RASTA: WPCode ID {$r->id} | '{$r->title}'\n";
					$hit = true; $found_any = true;
					break;
				}
			}
		}
		if ( ! $hit ) echo "  (nerasta)\n";
		echo "\n";
	}

	// ---------- 3) wp_posts (bet koks CPT, blokai, WPCode CPT) ----------
	echo "--- wp_posts (post_content) ---\n";
	$hit = false;
	foreach ( $markers as $m ) {
		$like = '%' . $wpdb->esc_like( $m ) . '%';
		$rows = $wpdb->get_results( $wpdb->prepare(
			"SELECT ID, post_title, post_type, post_status FROM {$wpdb->posts} WHERE post_content LIKE %s LIMIT 20",
			$like
		) );
		foreach ( (array) $rows as $r ) {
			echo "  RASTA: post ID {$r->ID} | type={$r->post_type} | status={$r->post_status} | '{$r->post_title}' (markeris: {$m})\n";
			$hit = true; $found_any = true;
		}
	}
	if ( ! $hit ) echo "  (nerasta)\n";
	echo "\n";

	// ---------- 4) Failu sistema (wp-content: themes, mu-plugins, plugins) ----------
	echo "--- Failai (wp-content/*.php) ---\n";
	$dirs = [
		get_stylesheet_directory(),                 // child tema
		get_template_directory(),                   // parent tema (Flatsome)
		defined('WPMU_PLUGIN_DIR') ? WPMU_PLUGIN_DIR : '',
		WP_PLUGIN_DIR,                              // visi plugin'ai
	];
	$dirs = array_values( array_unique( array_filter( $dirs ) ) );
	$hit = false;
	$scanned = 0;

	foreach ( $dirs as $dir ) {
		if ( ! is_dir( $dir ) ) continue;
		try {
			$it = new RecursiveIteratorIterator(
				new RecursiveDirectoryIterator( $dir, FilesystemIterator::SKIP_DOTS )
			);
			foreach ( $it as $file ) {
				if ( ! $file->isFile() ) continue;
				if ( strtolower( $file->getExtension() ) !== 'php' ) continue;
				// praleidziam vendor / node_modules (greitis)
				$path = $file->getPathname();
				if ( strpos( $path, '/vendor/' ) !== false || strpos( $path, '/node_modules/' ) !== false ) continue;
				$scanned++;
				$content = @file_get_contents( $path );
				if ( $content === false ) continue;
				foreach ( $markers as $m ) {
					if ( stripos( $content, $m ) !== false ) {
						echo "  RASTA: " . str_replace( WP_CONTENT_DIR, 'wp-content', $path ) . " (markeris: {$m})\n";
						$hit = true; $found_any = true;
						break;
					}
				}
			}
		} catch ( Exception $e ) {
			echo "  (klaida skenuojant {$dir}: " . $e->getMessage() . ")\n";
		}
	}
	echo "  Peržiūrėta .php failu: {$scanned}\n";
	if ( ! $hit ) echo "  (failuose nerasta)\n";
	echo "\n";

	echo $found_any ? "=== BAIGTA — radinys virsuje ===\n" : "=== BAIGTA — NIEKUR nerasta (gal kitas markeris?) ===\n";
	exit;
}, 1 );

