/**
 * FBT Inspect v1 (read-only)
 *
 * PASKIRTIS: suprasti, kodel FBT "Prideti pasirinktas" prideda tik
 * pagrindine preke, ne pazymetas companion prekes.
 *
 * Ka rodo:
 *   1. FBT plugin faila + "add to cart" / "selected" / form logika.
 *   2. Ar yra AJAX handler, ar form submit.
 *   3. FBT HTML strukturos pavyzdys (kaip checkbox'ai pavadinti).
 *
 * NIEKO NEKEICIA — tik skaito.
 *
 * NAUDOJIMAS: /wp-admin/?fbt_inspect=1
 * Po naudojimo deaktyvuoti.
 */

add_action( 'init', function () {

	if ( ! isset( $_GET['fbt_inspect'] ) ) return;
	if ( ! current_user_can( 'manage_options' ) ) return;

	header( 'Content-Type: text/html; charset=utf-8' );
	echo '<meta charset="utf-8"><body style="font-family:monospace;font-size:12px;padding:20px;line-height:1.5">';
	echo '<h2>FBT Inspect v1 (read-only)</h2>';

	// Surandam petshop-fbt.php
	$candidates = array(
		WP_PLUGIN_DIR . '/petshop-fbt/petshop-fbt.php',
		WP_PLUGIN_DIR . '/petshop-fbt.php',
	);
	// Ieskom ir per glob
	foreach ( glob( WP_PLUGIN_DIR . '/*/petshop-fbt.php' ) as $g ) $candidates[] = $g;
	foreach ( glob( WP_PLUGIN_DIR . '/petshop-fbt*.php' ) as $g ) $candidates[] = $g;

	$file = null;
	foreach ( array_unique( $candidates ) as $c ) {
		if ( file_exists( $c ) ) { $file = $c; break; }
	}

	if ( ! $file ) {
		echo '<p style="color:red">petshop-fbt.php nerastas. Tikrinu Code Snippets...</p>';
		// Gal FBT yra snippet'e
		global $wpdb;
		$snip = $wpdb->prefix . 'snippets';
		if ( $wpdb->get_var( "SHOW TABLES LIKE '$snip'" ) ) {
			$rows = $wpdb->get_results( "SELECT id, name, active FROM $snip WHERE code LIKE '%fbt%' OR code LIKE '%perkama kartu%' OR code LIKE '%frequently%'", ARRAY_A );
			foreach ( $rows as $r ) echo '<p>Snippet #' . $r['id'] . ': ' . esc_html( $r['name'] ) . ' (' . ( $r['active']?'aktyvus':'ne' ) . ')</p>';
		}
		echo '</body>'; exit;
	}

	echo '<p>FBT failas: <b>' . esc_html( str_replace( ABSPATH, '', $file ) ) . '</b></p>';
	$code = file_get_contents( $file );
	echo '<p>Dydis: ' . strlen( $code ) . ' baitu, ' . substr_count( $code, "\n" ) . ' eiluciu.</p>';

	// Versija
	if ( preg_match( '/Version:\s*([0-9.]+)/i', $code, $m ) ) {
		echo '<p>Versija: <b>' . $m[1] . '</b></p>';
	}

	// Raktiniai zodziai
	$keywords = array(
		'add-to-cart', 'add_to_cart', 'WC()->cart->add_to_cart', 'wc_add_to_cart',
		'selected', 'checkbox', 'wp_ajax', 'admin-ajax', 'nonce', '_petshop_fbt',
		'$_POST', '$_GET', 'fbt_ids', 'companion'
	);
	echo '<h3>Raktiniu zodziu vietos:</h3><table border="1" cellpadding="4" cellspacing="0"><tr><th>Raktas</th><th>Kiek kartu</th></tr>';
	foreach ( $keywords as $k ) {
		$n = substr_count( strtolower( $code ), strtolower( $k ) );
		if ( $n > 0 ) echo '<tr><td>' . esc_html( $k ) . '</td><td>' . $n . '</td></tr>';
	}
	echo '</table>';

	// Parodom eilutes susijusias su add to cart / selected / POST
	echo '<h3>Svarbios eilutes (add to cart / selected / POST / AJAX):</h3>';
	$lines = explode( "\n", $code );
	echo '<div style="background:#f5f5f5;padding:10px">';
	foreach ( $lines as $i => $ln ) {
		$lc = strtolower( $ln );
		if ( strpos($lc,'add_to_cart')!==false || strpos($lc,'add-to-cart')!==false ||
		     strpos($lc,'selected')!==false || strpos($lc,'$_post')!==false ||
		     strpos($lc,'$_get')!==false || strpos($lc,'wp_ajax')!==false ||
		     strpos($lc,'checkbox')!==false || strpos($lc,'fbt_ids')!==false ||
		     strpos($lc,'->add_to_cart')!==false ) {
			echo '<div style="border-bottom:1px solid #ddd;padding:2px 0"><b>eil.' . ($i+1) . ':</b> ' . esc_html( trim( $ln ) ) . '</div>';
		}
	}
	echo '</div>';

	echo '<hr><p style="color:#666">Read-only. Atsiusk si rezultata — pamatysim, kaip FBT prideda prekes ir kur luzta. Po naudojimo deaktyvuoti.</p></body>';
	exit;
} );

