			'stock'=>get_post_meta($pid,'_stock',true),
		);
	}
	$o['results']=$results;
	// suvestine
	$safe=0;$has_active=0;$has_history=0;
	foreach($results as $r){
		if(!($r['exists']??false))continue;
		if(($r['active_orders']??0)>0)$has_active++;
		elseif(($r['total_orders']??0)>0)$has_history++;
		else $safe++;
	}
	$o['summary']=array('visiskai_saugu'=>$safe,'turi_istorija_bet_ne_aktyvu'=>$has_history,'TURI_AKTYVIU_UZSAKYMU'=>$has_active);
	header('Content-Type: application/json'); echo json_encode($o); exit;
});
